using System;using UnityEngine;
namespace FashionFit {
 [DefaultExecutionOrder(200)]
 public sealed class PoseWearable:MonoBehaviour {
  public RunwayPoseRig Rig{get;private set;}public int Look{get;private set;}public ElasticSurface Surface{get;private set;}
  public uint SolverVersion{get;private set;}public double SolveMilliseconds{get;private set;}public double PublishMilliseconds{get;private set;}
  public HeadFitSupport Head{get;private set;}public double Milliseconds{get;private set;}public double SkinMilliseconds{get;private set;}public double SurfaceMilliseconds{get;private set;}
  RunwayAvatar avatar;GameObject outfit;Vector3[] rest,anchors;BoneWeight[] weights;Matrix4x4[] matrices,last;Mesh bodyBake;PoseDeformationJob deformer;PoseBodyField field;Matrix4x4[] skin,inverseSkin;BoneWeight[] bindingWeights;
  Matrix4x4 bodyToWorld,worldToBody;float accumulator;bool first=true;int[] garmentTriangles;Proxy[] proxies;
  struct Proxy{public Transform a,b;public int bone;public float radius;public Vector3 start,end,min,max,neutralStart,neutralEnd,endInBone;}
  public void Initialize(RunwayPoseRig rig){Rig=rig;avatar=rig.Avatar;Head=avatar.gameObject.GetComponent<HeadFitSupport>();if(!Head){Head=avatar.gameObject.AddComponent<HeadFitSupport>();Head.Initialize(avatar);}bodyBake=new Mesh();matrices=new Matrix4x4[avatar.Bones.Length];last=new Matrix4x4[matrices.Length];}
  public void Wear(int look){if(Surface&&(Surface.GrabCount>0||(Surface.ContactMotion&&Surface.ContactMotion.SupportCount>0))){Rig.Owner.Report("Thả Grip và tay mannequin đang giữ vải trước khi thay mẫu");return;}Clear();Look=Mathf.Clamp(look,1,Rig.Label.Contains("nữ")?6:11);string gender=Rig.Label.Contains("nữ")?"Female":"Male";var asset=MensReferenceCollection.Contains(Look)?MensReferenceCollection.Asset(Look):Resources.Load<PoseOutfitAsset>("PoseWardrobe/"+gender+Look.ToString("00"));if(!asset||!asset.mesh)throw new InvalidOperationException("Thiếu trang phục pose "+gender+Look);
   outfit=new GameObject(asset.label);outfit.transform.SetParent(avatar.transform,false);outfit.layer=9;outfit.AddComponent<MeshFilter>().sharedMesh=asset.mesh;outfit.AddComponent<MeshRenderer>().sharedMaterials=asset.materials;
   rest=asset.mesh.vertices;weights=asset.mesh.boneWeights;anchors=new Vector3[rest.Length];Surface=outfit.AddComponent<ElasticSurface>();Surface.Initialize(MembraneMaterial.Presets[0]);Surface.EnablePoseDriver();Surface.SuspensionY=avatar.BodyMesh.bounds.max.y*.625f;BuildBindings(asset.mesh);
   var box=outfit.AddComponent<BoxCollider>();box.isTrigger=true;box.center=asset.mesh.bounds.center;box.size=asset.mesh.bounds.size+Vector3.one*.03f;outfit.AddComponent<RunwayVRGrabTarget>().ConfigureElastic(Surface);
   first=true;Step(1f/30);ContactGarment.Attach(Rig.Owner,Surface);
  }
  public void Clear(){if(deformer!=null){deformer.Dispose();deformer=null;}if(outfit){outfit.SetActive(false);if(Application.isPlaying)Destroy(outfit);else DestroyImmediate(outfit);}outfit=null;Surface=null;Look=0;}
  public void SetMaterial(MembraneMaterial material){if(Surface)Surface.SetMaterial(material);}
  void LateUpdate(){accumulator+=Time.deltaTime;bool interacting=Surface&&(Surface.GrabCount>0||(Rig&&Rig.IsHeld));if(interacting||accumulator>=1f/30){float dt=Mathf.Min(accumulator,.05f);accumulator=0;Step(dt);}}
  public void Step(float dt){Milliseconds=0;if(!Surface)return;avatar.FillSkinMatrices(matrices);bool changed=first;for(int i=0;i<matrices.Length&&!changed;i++)for(int j=0;j<16;j++)if(Mathf.Abs(matrices[i][j]-last[i][j])>1e-5f){changed=true;break;}
   if(!changed&&Surface.ContactMotion&&Surface.ContactMotion.Active)return;if(!changed&&!Surface.NeedsUpdate)return;bodyToWorld=avatar.transform.localToWorldMatrix;worldToBody=avatar.transform.worldToLocalMatrix;var timer=System.Diagnostics.Stopwatch.StartNew();
   if(changed){UpdateProxies();for(int i=0;i<proxies.Length;i++){var p=proxies[i];// The full body field already covers neutral limbs. Activate the
     // conservative cross-limb proxy only after the limb actually moves.
     bool moved=(p.start-p.neutralStart).sqrMagnitude>.0001f||(p.end-p.neutralEnd).sqrMagnitude>.0001f;deformer.SetCapsule(i,p.start,p.end,moved?p.radius:0,p.bone);}Array.Copy(matrices,last,matrices.Length);first=false;}
   SkinMilliseconds=timer.Elapsed.TotalMilliseconds;deformer.Run(matrices,Surface,dt,changed,worldToBody.MultiplyVector(Physics.gravity),avatar.BodyMesh.bounds.max.y*.625f);SurfaceMilliseconds=timer.Elapsed.TotalMilliseconds-SkinMilliseconds;SolveMilliseconds=deformer.SolveMilliseconds;PublishMilliseconds=deformer.PublishMilliseconds;SolverVersion++;var box=outfit.GetComponent<BoxCollider>();box.center=Surface.MeshAt(0).bounds.center;box.size=Surface.MeshAt(0).bounds.size+Vector3.one*.03f;timer.Stop();Milliseconds=timer.Elapsed.TotalMilliseconds;
  }
  void BuildBindings(Mesh mesh){
   if(field==null)field=new PoseBodyField(Rig.Label.Contains("nữ")?"Female":"Male");garmentTriangles=mesh.triangles;bindingWeights=new BoneWeight[rest.Length+garmentTriangles.Length/3];Array.Copy(weights,bindingWeights,weights.Length);
   for(int i=0;i<garmentTriangles.Length;i+=3)bindingWeights[rest.Length+i/3]=Blend(weights[garmentTriangles[i]],weights[garmentTriangles[i+1]],weights[garmentTriangles[i+2]]);
   deformer=new PoseDeformationJob(rest,bindingWeights,garmentTriangles,avatar.Bones.Length,field);
   string[] names={"LeftArm","LeftForeArm","RightArm","RightForeArm","LeftUpLeg","LeftLeg","RightUpLeg","RightLeg","LeftFoot","RightFoot"};string[] tips={"LeftForeArm","LeftHand","RightForeArm","RightHand","LeftLeg","LeftFoot","RightLeg","RightFoot","LeftToeBase","RightToeBase"};proxies=new Proxy[names.Length];var bw=avatar.BodyMesh.boneWeights;
   for(int k=0;k<names.Length;k++){int bone=avatar.BoneIndex(names[k]);Vector3 a=avatar.GarmentBindposes[bone].inverse.MultiplyPoint3x4(Vector3.zero),b=k>=8?a+new Vector3(0,-.04f,.13f):avatar.GarmentBindposes[avatar.BoneIndex(tips[k])].inverse.MultiplyPoint3x4(Vector3.zero),line=b-a;float radius=.025f;for(int i=0;i<avatar.BodyVertices.Length;i++){var w=bw[i];float weight=w.boneIndex0==bone?w.weight0:w.boneIndex1==bone?w.weight1:w.boneIndex2==bone?w.weight2:w.boneIndex3==bone?w.weight3:0;if(weight<.6f)continue;Vector3 p=avatar.BodyVertices[i];float u=Vector3.Dot(p-a,line)/Mathf.Max(1e-8f,line.sqrMagnitude);if(u<.08f||u>.92f)continue;radius=Mathf.Max(radius,Vector3.Distance(p,a+line*u));}proxies[k]=new Proxy{a=avatar.FindJoint(names[k]),b=avatar.FindJoint(tips[k]),bone=bone,radius=radius+.020f,neutralStart=a,neutralEnd=b,endInBone=avatar.GarmentBindposes[bone].MultiplyPoint3x4(b)};}
  }
  void UpdateProxies(){for(int i=0;i<proxies.Length;i++){var p=proxies[i];p.start=worldToBody.MultiplyPoint3x4(p.a.position);p.end=worldToBody.MultiplyPoint3x4(p.b?p.b.position:p.a.TransformPoint(p.endInBone));p.min=Vector3.Min(p.start,p.end)-Vector3.one*p.radius;p.max=Vector3.Max(p.start,p.end)+Vector3.one*p.radius;proxies[i]=p;}}
  static BoneWeight Blend(BoneWeight a,BoneWeight b,BoneWeight c){var sum=new System.Collections.Generic.Dictionary<int,float>();foreach(var w in new[]{a,b,c}){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] values={w.weight0,w.weight1,w.weight2,w.weight3};for(int i=0;i<4;i++)if(values[i]>0)sum[ids[i]]=(sum.TryGetValue(ids[i],out float old)?old:0)+values[i];}var sorted=new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<int,float>>(sum);sorted.Sort((x,y)=>y.Value.CompareTo(x.Value));int[] id=new int[4];float[] value=new float[4];float total=0;for(int i=0;i<4&&i<sorted.Count;i++){id[i]=sorted[i].Key;value[i]=sorted[i].Value;total+=value[i];}return new BoneWeight{boneIndex0=id[0],boneIndex1=id[1],boneIndex2=id[2],boneIndex3=id[3],weight0=value[0]/total,weight1=value[1]/total,weight2=value[2]/total,weight3=value[3]/total};}
  void OnDestroy(){if(deformer!=null)deformer.Dispose();if(field!=null)field.Dispose();if(bodyBake){if(Application.isPlaying)Destroy(bodyBake);else DestroyImmediate(bodyBake);}}
 }
}
